import{_ as l,h as i,o as t,a9 as a}from"./chunks/framework.C3Rk_ney.js";const g=JSON.parse('{"title":"在 Windows 上的 IIS 服务器安装 SSL 证书（阿里云）","description":"","frontmatter":{"title":"在 Windows 上的 IIS 服务器安装 SSL 证书（阿里云）","date":"2026-08-03T10:35:40.000Z","tags":["SSL证书","IIS服务器","Windows"],"head":[["script",{},"!function(p){\\"use strict\\";!function(t){var s=window,e=document,i=p,c=\\"\\".concat(\\"https:\\"===e.location.protocol?\\"https://\\":\\"http://\\",\\"sdk.51.la/js-sdk-pro.min.js\\"),n=e.createElement(\\"script\\"),r=e.getElementsByTagName(\\"script\\")[0];n.type=\\"text/javascript\\",n.setAttribute(\\"charset\\",\\"UTF-8\\"),n.async=!0,n.src=c,n.id=\\"LA_COLLECT\\",i.d=n;var o=function(){s.LA.ids.push(i)};s.LA?s.LA.ids&&o():(s.LA=p,s.LA.ids=[],o()),r.parentNode.insertBefore(n,r)}()}({\\"id\\":\\"3O7uab6Jff8eGzAT\\",\\"ck\\":\\"3O7uab6Jff8eGzAT\\",\\"hashMode\\":true});"]]},"headers":[],"relativePath":"daily-notes/2026/windows-iis-ssl.md","filePath":"daily-notes/2026/windows-iis-ssl.md","lastUpdated":1785722503000}'),s={name:"daily-notes/2026/windows-iis-ssl.md"},e=a('<h1 id="在-windows-上的-iis-服务器安装-ssl-证书-阿里云" tabindex="-1">在 Windows 上的 IIS 服务器安装 SSL 证书（阿里云） <a class="header-anchor" href="#在-windows-上的-iis-服务器安装-ssl-证书-阿里云" aria-label="Permalink to &quot;在 Windows 上的 IIS 服务器安装 SSL 证书（阿里云）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">背景</p><p>老旧服务器，怕以后阿里云删除帮助文档，固记录备用。</p></div><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h2><h3 id="步骤一-准备ssl证书" tabindex="-1">步骤一：准备SSL证书 <a class="header-anchor" href="#步骤一-准备ssl证书" aria-label="Permalink to &quot;步骤一：准备SSL证书&quot;">​</a></h3><p>在阿里云控制台-数字证书管理服务-购买、创建、部署。</p><p>详略。</p><h3 id="步骤二-配置系统与网络环境" tabindex="-1">步骤二：配置系统与网络环境 <a class="header-anchor" href="#步骤二-配置系统与网络环境" aria-label="Permalink to &quot;步骤二：配置系统与网络环境&quot;">​</a></h3><ol><li>开放安全组的 443 端口。</li><li>开放服务器防火墙的443端口。</li></ol><p>详略。</p><h3 id="步骤三-在mmc导入ssl证书-重点" tabindex="-1">步骤三：在MMC导入SSL证书（重点） <a class="header-anchor" href="#步骤三-在mmc导入ssl证书-重点" aria-label="Permalink to &quot;步骤三：在MMC导入SSL证书（重点）&quot;">​</a></h3><ol><li><p>单击左下角开始菜单，搜索并打开运行对话框，输入mmc，单击确定。</p></li><li><p>在MMC控制台，添加证书管理单元。</p><ul><li><p>控制台的顶部菜单栏，选择。</p></li><li><p>在添加或删除管理单元对话框，从左侧可用的管理单元列表中选择证书，单击添加。添加或删除管理单元界面</p></li></ul><p><img src="https://cdn.jsdelivr.net/gh/jonaslgtm/fucang-imgs@latest/help-static-aliyun-01.png" alt="alt text" loading="lazy"></p><ul><li><p>在证书管理单元对话框，选择计算机账户，单击下一步。</p></li><li><p>在选择计算机对话框，选择本地计算机（运行此控制台的计算机），单击完成。</p></li><li><p>在添加或删除管理单元对话框，单击确定。</p></li></ul></li><li><p>在控制台左侧导航栏，展开，然后将光标放置在个人并单击鼠标右键，选择。打开证书导入向导</p><p><img src="https://cdn.jsdelivr.net/gh/jonaslgtm/fucang-imgs@latest/help-static-aliyun-02.png" alt="alt text" loading="lazy"></p></li><li><p>根据对话框提示，完成证书导入向导。</p><ul><li><p>欢迎使用证书导入向导：单击下一步。</p></li><li><p>要导入的文件对话框：单击浏览，打开PFX格式的证书文件，单击下一步。</p><p><img src="https://cdn.jsdelivr.net/gh/jonaslgtm/fucang-imgs@latest/help-static-aliyun-03.png" alt="alt text" loading="lazy"></p></li><li><p>在打开文件时，您必须先将文件类型设置为所有文件（*），然后再选择证书文件。</p></li><li><p>为私钥键入密码：打开TXT格式的私钥文件，复制文件内容，并将内容粘贴在密码文本框，单击下一步。</p></li><li><p>证书存储：选中根据证书类型，自动选择证书存储，单击下一步。</p></li><li><p>正在完成证书导入向导：单击完成。</p></li><li><p>收到导入成功提示后，单击确定。</p></li></ul></li></ol><h3 id="步骤四-在iis管理器为网站绑定ssl证书-重点" tabindex="-1">步骤四：在IIS管理器为网站绑定SSL证书（重点） <a class="header-anchor" href="#步骤四-在iis管理器为网站绑定ssl证书-重点" aria-label="Permalink to &quot;步骤四：在IIS管理器为网站绑定SSL证书（重点）&quot;">​</a></h3><p>老版本：<strong>Windows Server 2008 R2</strong></p><ol><li><p>添加网站绑定。请根据服务器操作系统的版本选择相应的操作步骤。 单击开始菜单，单击。</p><ul><li>在左侧连接区域，展开服务器，单击网站，在网站列表单击对应的网站，在右侧操作区域，单击绑定。</li></ul><p><img src="https://cdn.jsdelivr.net/gh/jonaslgtm/fucang-imgs@latest/help-static-aliyun-04.png" alt="alt text" loading="lazy"></p><ul><li><p>在网站绑定对话框，单击添加。</p></li><li><p>在添加网站绑定对话框，完成网站的相关配置，并单击确定。请根据以下两种业务场景进行选择。</p></li><li><p>为单个网站配置证书：只需要为 IIS 服务器上的一个网站配置证书，或多个网站配置同一个证书。</p></li></ul></li></ol><p><strong>为单个网站配置证书</strong></p><p><img src="https://cdn.jsdelivr.net/gh/jonaslgtm/fucang-imgs@latest/help-static-aliyun-05.png" alt="alt text" loading="lazy"></p><ul><li><p>类型：选择https。</p></li><li><p>IP地址：选择服务器的IP地址。当网站部署在本服务器上且本服务器不存在多个IP地址的情况时，保持全部未分配即可。</p></li><li><p>端口：默认为443，无需修改。</p></li></ul><p><strong>说明</strong></p><ul><li><p>建议端口设置为 443。若设置为非 443 端口，则通过浏览器访问网站时，必须在网站域名后添加端口号（例如：<a href="https://domain.com:8443%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://domain.com:8443）。</a></p></li><li><p>SSL证书：选择已导入的证书。</p></li><li><p>完成配置后，您可以在网站绑定列表查看已添加的https类型网站绑定。</p></li></ul>',19),p=[e];function n(o,r,c,d,h,u){return t(),i("div",null,p)}const S=l(s,[["render",n]]);export{g as __pageData,S as default};
